<?php if(!$orders): ?><div class="empty"><h3>Todavía no hay pedidos.</h3><p>Los nuevos pedidos van a aparecer acá.</p></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Total</th><th>Pago</th><th>Fabricación</th><th></th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><span class="admin-order-number">#<?= (int)$o['id'] ?><?php if(array_key_exists('admin_reviewed_at',$o) && $o['admin_reviewed_at']===null): ?><span class="admin-order-unread" title="Pedido nuevo sin revisar"><span class="sr-only">Pedido nuevo sin revisar</span></span><?php endif ?></span><small><?= date('d/m/Y',strtotime($o['created_at'])) ?></small></td><td><?= e($o['customer_name']) ?><small><?= e($o['email']) ?></small></td><td><?= money($o['total_cents']) ?></td><td><?= paymentBadge($o['payment_status']) ?></td><td><?= fabricationBadge($o['status']) ?></td><td><div class="admin-row-actions"><a class="text-link" href="/admin/pedidos/<?= $o['id'] ?>">Ver ↗</a><?php if(hasOrderDeletion()): ?><form method="post" action="/admin/pedidos/<?= (int)$o['id'] ?>/eliminar"><?= csrf() ?><button type="submit" class="cart-remove admin-delete-button" aria-label="Eliminar pedido #<?= (int)$o['id'] ?>" title="Eliminar pedido del panel" data-confirm="¿Eliminar este pedido del panel? Los pagos y el historial del cliente se conservarán. Esta acción no reintegra el dinero."><?php require ROOT.'/views/trash-icon.php'; ?></button></form><?php endif ?></div></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
